     app.get('/_teste/relogio', (req, res) => {
       res.status(200).json({ agora: relogio });
     });

     app.put('/_teste/relogio', (req, res) => {
       relogio = req.body.agora;
       res.status(200).json({ agora: relogio });
     });
   }

-  // Middleware para verificação de usuário (R1)
